ALTER TABLE "leads" ADD CONSTRAINT "leads_lost_reason_consistent" CHECK (("status"='lost')=("lost_reason" IS NOT NULL)) NOT VALID;
ALTER TABLE "leads" ADD CONSTRAINT "leads_lost_reason_length" CHECK ("lost_reason" IS NULL OR length(trim("lost_reason")) BETWEEN 1 AND 1000) NOT VALID;
CREATE TABLE "lead_status_events"("id" text PRIMARY KEY,"organization_id" text NOT NULL,"lead_id" text NOT NULL,"from_status" "lead_status","to_status" "lead_status" NOT NULL,"reason" text,"occurred_at" timestamptz DEFAULT now() NOT NULL,"idempotency_key" text NOT NULL,"created_by" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT,CONSTRAINT "lead_status_events_id_format" CHECK ("id"~'^lse_[a-z0-9_-]{6,64}$'),CONSTRAINT "lead_status_events_reason_length" CHECK ("reason" IS NULL OR length(trim("reason")) BETWEEN 1 AND 1000),CONSTRAINT "lead_status_events_status_change" CHECK ("from_status" IS NULL OR "from_status"<>"to_status"),CONSTRAINT "lead_status_events_same_lead_fk" FOREIGN KEY("organization_id","lead_id") REFERENCES "leads"("organization_id","id"));
CREATE UNIQUE INDEX "lead_status_events_organization_id_unique" ON "lead_status_events"("organization_id","id");CREATE UNIQUE INDEX "lead_status_events_idempotency_unique" ON "lead_status_events"("organization_id","idempotency_key");CREATE INDEX "lead_status_events_lead_time_idx" ON "lead_status_events"("organization_id","lead_id","occurred_at");
ALTER TABLE "lead_status_events" ENABLE ROW LEVEL SECURITY;ALTER TABLE "lead_status_events" FORCE ROW LEVEL SECURITY;CREATE POLICY "lead_status_events_current_tenant_select" ON "lead_status_events" FOR SELECT USING("organization_id"=nullif(current_setting('app.organization_id',true),''));CREATE POLICY "lead_status_events_current_tenant_insert" ON "lead_status_events" FOR INSERT WITH CHECK("organization_id"=nullif(current_setting('app.organization_id',true),''));
CREATE FUNCTION prevent_lead_authority_rewrite() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.organization_id<>OLD.organization_id OR NEW.location_id IS DISTINCT FROM OLD.location_id OR NEW.customer_id<>OLD.customer_id OR NEW.source<>OLD.source OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION 'lead authority fields are immutable';END IF;RETURN NEW;END $$;CREATE TRIGGER "leads_authority_immutable" BEFORE UPDATE ON "leads" FOR EACH ROW EXECUTE FUNCTION prevent_lead_authority_rewrite();
